test('successful callback records incident recovery evidence without resolving case',()=>{const {createHmac}=require('node:crypto');const db=openStore(':memory:');const payments=createPaymentAuthority({db}),orders=createOrderAuthority({db}),secret='recovery-evidence-secret';const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:610,currency:'KES',idempotencyKey:'recovery-evidence-order'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:o.total});const p=payments.createCommercePayment({orderId:o.id});const mpesa=createMpesaAdapter({webhookSecret:secret,initiate:req=>({providerRequestId:'recovery-'+req.correlationId})}),intents=createPaymentIntentAuthority({db,providers:{mpesa}}),boundary=createProviderBoundary({db,paymentAuthority:payments,providers:{mpesa}});const intent=intents.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'mpesa',customerContact:'254700000099',idempotencyKey:'recovery-evidence-intent'});intents.process({intentId:intent.id});const now=new Date().toISOString();db.prepare("INSERT INTO support_cases(id,incident_type,severity,affected_entity,correlation_id,status,idempotency_key,version,created_at,updated_at) VALUES('case-recovery','PAYMENT_CALLBACK','HIGH',?,?,'IN_PROGRESS','case-recovery-key',1,?,?)").run(p.id,intent.correlation_id,now,now);db.prepare("INSERT INTO support_cases(id,incident_type,severity,affected_entity,correlation_id,status,idempotency_key,version,created_at,updated_at) VALUES('case-conflict','PAYMENT_CALLBACK','HIGH',?,?,'IN_PROGRESS','case-conflict-key',1,?,?)").run(p.id,'wrong-correlation',now,now);const raw=JSON.stringify({eventId:'evt-recovery-evidence',correlationId:intent.correlation_id,paymentKind:'commerce_payment',paymentId:p.id,type:'PAYMENT_SUCCEEDED',reference:'MPESA610',amount:610,currency:'KES'}),sig=createHmac('sha256',secret).update(raw).digest('hex');boundary.handle({provider:'mpesa',rawBody:raw,signature:sig});const event=db.prepare("SELECT * FROM support_case_events WHERE case_id='case-recovery' AND event_type='PAYMENT_CALLBACK_RECOVERED'").get();assert.ok(event);assert.equal(event.evidence_ref,'provider-callback:evt-recovery-evidence');assert.equal(db.prepare("SELECT status FROM support_cases WHERE id='case-recovery'").get().status,'IN_PROGRESS');assert.equal(db.prepare("SELECT COUNT(*) AS n FROM support_case_events WHERE case_id='case-conflict' AND event_type='PAYMENT_CALLBACK_RECOVERED'").get().n,0);boundary.handle({provider:'mpesa',rawBody:raw,signature:sig});assert.equal(db.prepare("SELECT COUNT(*) AS n FROM support_case_events WHERE case_id='case-recovery' AND event_type='PAYMENT_CALLBACK_RECOVERED'").get().n,1);db.close();});

test('callback failure schedules retry and dead letters at max attempts',()=>{const db=openStore(':memory:');const now=new Date().toISOString();db.prepare("INSERT INTO provider_callback_inbox(id,provider,provider_event_id,correlation_id,payment_kind,payment_id,event_type,reference,amount,currency,payload_hash,normalized_event,status,attempts,received_at,updated_at,next_attempt_at) VALUES('retry','test','evt-retry','corr-retry','commerce_payment','pay-retry','PAYMENT_SUCCEEDED','ref-retry',1,'KES','hash-retry','{}','RECEIVED',0,?,?,?)").run(now,now,now);const authority={verifyCommerceProviderInsideTransaction:()=>{throw Object.assign(new Error('DOWN'),{code:'DOWN'})},verifyBookingProviderInsideTransaction:()=>{}};const boundary=createProviderBoundary({db,paymentAuthority:authority,providers:{},maxAttempts:2,baseBackoffMs:1000});assert.throws(()=>boundary.process({inboxId:'retry',workerId:'w1'}));let row=db.prepare("SELECT * FROM provider_callback_inbox WHERE id='retry'").get();assert.equal(row.status,'FAILED');assert.equal(row.attempts,1);assert.ok(row.next_attempt_at>row.updated_at);db.prepare("UPDATE provider_callback_inbox SET next_attempt_at=? WHERE id='retry'").run(new Date(Date.now()-1000).toISOString());assert.throws(()=>boundary.process({inboxId:'retry',workerId:'w2'}));row=db.prepare("SELECT * FROM provider_callback_inbox WHERE id='retry'").get();assert.equal(row.status,'DEAD_LETTER');assert.equal(row.attempts,2);assert.equal(row.next_attempt_at,null);assert.equal(boundary.processDue({workerId:'w3',limit:10}).length,0);db.close();});

