test('stale callback worker cannot settle after lease ownership changes',()=>{const db=openStore(':memory:');const now=new Date().toISOString();db.prepare("INSERT INTO provider_callback_inbox(id,provider,provider_event_id,correlation_id,payment_kind,payment_id,event_type,reference,amount,currency,payload_hash,normalized_event,status,attempts,received_at,updated_at,lease_owner,lease_expires_at) VALUES('stale','test','evt-stale','corr-stale','commerce_payment','pay-stale','PAYMENT_SUCCEEDED','ref-stale',1,'KES','hash-stale','{}','PROCESSING',1,?,?,?,?)").run(now,now,'worker-b',new Date(Date.now()+60000).toISOString());const boundary=createProviderBoundary({db,paymentAuthority:{},providers:{}});assert.throws(()=>boundary.process({inboxId:'stale',workerId:'worker-a'}),e=>e.code==='PROVIDER_CALLBACK_LEASED');assert.equal(db.prepare("SELECT lease_owner FROM provider_callback_inbox WHERE id='stale'").get().lease_owner,'worker-b');db.close();});



test('exhausted callback claim durably transitions to dead letter before terminal error',()=>{const db=openStore(':memory:');const now=new Date().toISOString();db.prepare("INSERT INTO provider_callback_inbox(id,provider,provider_event_id,correlation_id,payment_kind,payment_id,event_type,reference,amount,currency,payload_hash,normalized_event,status,attempts,received_at,updated_at,next_attempt_at) VALUES('exhausted-claim','test','evt-exhausted-claim','corr-exhausted-claim','commerce_payment','pay-exhausted-claim','PAYMENT_SUCCEEDED','ref-exhausted-claim',1,'KES','hash-exhausted-claim','{}','FAILED',5,?,?,?)").run(now,now,now);const boundary=createProviderBoundary({db,paymentAuthority:{},providers:{},maxAttempts:5});assert.throws(()=>boundary.claim({inboxId:'exhausted-claim',workerId:'terminal-worker'}),e=>e.code==='PROVIDER_CALLBACK_DEAD_LETTER');const row=db.prepare("SELECT status,attempts,lease_owner,lease_expires_at FROM provider_callback_inbox WHERE id='exhausted-claim'").get();assert.equal(row.status,'DEAD_LETTER');assert.equal(row.attempts,5);assert.equal(row.lease_owner,null);assert.equal(row.lease_expires_at,null);db.close();});

test('same callback worker identity cannot use a stale lease generation after reacquire',()=>{const db=openStore(':memory:');const now=new Date().toISOString();db.prepare("INSERT INTO provider_callback_inbox(id,provider,provider_event_id,correlation_id,payment_kind,payment_id,event_type,reference,amount,currency,payload_hash,normalized_event,status,attempts,received_at,updated_at) VALUES('same-worker-generation','test','evt-same-worker-generation','corr-same-worker-generation','commerce_payment','pay-same-worker-generation','PAYMENT_SUCCEEDED','ref-same-worker-generation',1,'KES','hash-same-worker-generation','{}','RECEIVED',0,?,?)").run(now,now);const boundary=createProviderBoundary({db,paymentAuthority:{},providers:{},leaseMs:60000});const first=boundary.claim({inboxId:'same-worker-generation',workerId:'worker-same'});assert.equal(first.lease_version,1);db.prepare("UPDATE provider_callback_inbox SET lease_expires_at=? WHERE id='same-worker-generation'").run(new Date(Date.now()-1000).toISOString());const second=boundary.claim({inboxId:'same-worker-generation',workerId:'worker-same'});assert.equal(second.lease_version,2);assert.equal(second.lease_owner,'worker-same');assert.equal(second.attempts,2);assert.notEqual(first.lease_version,second.lease_version);const current=db.prepare("SELECT lease_version,lease_owner,status FROM provider_callback_inbox WHERE id='same-worker-generation'").get();assert.equal(current.lease_version,2);assert.equal(current.lease_owner,'worker-same');assert.equal(current.status,'PROCESSING');db.close();});


test('stale same-worker lease generation cannot finalize success or failure after reacquire',()=>{const db=openStore(':memory:');const now=new Date().toISOString();db.prepare("INSERT INTO provider_callback_inbox(id,provider,provider_event_id,correlation_id,payment_kind,payment_id,event_type,reference,amount,currency,payload_hash,normalized_event,status,attempts,received_at,updated_at) VALUES('generation-fence','test','evt-generation-fence','corr-generation-fence','commerce_payment','pay-generation-fence','PAYMENT_SUCCEEDED','ref-generation-fence',1,'KES','hash-generation-fence','{}','RECEIVED',0,?,?)").run(now,now);const boundary=createProviderBoundary({db,paymentAuthority:{},providers:{},leaseMs:60000});const first=boundary.claim({inboxId:'generation-fence',workerId:'worker-same'});db.prepare("UPDATE provider_callback_inbox SET lease_expires_at=? WHERE id='generation-fence'").run(new Date(Date.now()-1000).toISOString());const second=boundary.claim({inboxId:'generation-fence',workerId:'worker-same'});assert.equal(first.lease_version,1);assert.equal(second.lease_version,2);const success=db.prepare("UPDATE provider_callback_inbox SET status='PROCESSED',lease_owner=NULL,lease_expires_at=NULL,updated_at=? WHERE id=? AND status='PROCESSING' AND lease_owner=? AND lease_version=? AND lease_expires_at>?").run(new Date().toISOString(),'generation-fence','worker-same',first.lease_version,new Date().toISOString());assert.equal(success.changes,0);let current=db.prepare("SELECT status,lease_owner,lease_version FROM provider_callback_inbox WHERE id='generation-fence'").get();assert.equal(current.status,'PROCESSING');assert.equal(current.lease_owner,'worker-same');assert.equal(current.lease_version,second.lease_version);const failure=db.prepare("UPDATE provider_callback_inbox SET status='FAILED',last_error='STALE',lease_owner=NULL,lease_expires_at=NULL,updated_at=? WHERE id=? AND status='PROCESSING' AND lease_owner=? AND lease_version=?").run(new Date().toISOString(),'generation-fence','worker-same',first.lease_version);assert.equal(failure.changes,0);current=db.prepare("SELECT status,lease_owner,lease_version,last_error FROM provider_callback_inbox WHERE id='generation-fence'").get();assert.equal(current.status,'PROCESSING');assert.equal(current.lease_owner,'worker-same');assert.equal(current.lease_version,second.lease_version);assert.notEqual(current.last_error,'STALE');db.close();});

test('provider callback runtime drains bounded recovery backlog and stops cleanly',()=>{let calls=0,cleared=false;const boundary={processDue:({limit})=>{calls++;assert.equal(limit,3);return [{ok:true}]}};const runtime=createProviderCallbackRuntime({boundary,batchSize:3,setIntervalFn:()=>({unref(){}}),clearIntervalFn:()=>{cleared=true;}});runtime.start();assert.equal(calls,1);runtime.stop();assert.equal(cleared,true);assert.deepEqual(runtime.drain(),[]);});

test('provider callback processDue recovers received and expired processing rows',()=>{const db=openStore(':memory:');const now=new Date().toISOString(),past=new Date(Date.now()-60000).toISOString();for(const [id,status,lease] of [['r','RECEIVED',null],['x','PROCESSING',past]])db.prepare("INSERT INTO provider_callback_inbox(id,provider,provider_event_id,correlation_id,payment_kind,payment_id,event_type,reference,amount,currency,payload_hash,normalized_event,status,attempts,received_at,updated_at,lease_owner,lease_expires_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)").run(id,'test','evt-'+id,'corr-'+id,'commerce_payment','pay-'+id,'PAYMENT_SUCCEEDED','ref-'+id,1,'KES','hash-'+id,'{}',status,0,now,now,lease?'old-worker':null,lease);const seen=[];const authority={verifyCommerceProviderInsideTransaction:()=>{throw Object.assign(new Error('EXPECTED_TEST_STOP'),{code:'EXPECTED_TEST_STOP'})},verifyBookingProviderInsideTransaction:()=>{}};const boundary=createProviderBoundary({db,paymentAuthority:authority,providers:{}});const results=boundary.processDue({workerId:'recovery',limit:10});assert.equal(results.length,2);assert.equal(results.every(x=>x.ok===false),true);assert.deepEqual(results.map(x=>x.inboxId).sort(),['r','x']);assert.equal(db.prepare("SELECT status FROM provider_callback_inbox WHERE id='r'").get().status,'FAILED');assert.equal(db.prepare("SELECT status,lease_owner FROM provider_callback_inbox WHERE id='x'").get().status,'FAILED');assert.equal(db.prepare("SELECT lease_owner FROM provider_callback_inbox WHERE id='x'").get().lease_owner,null);db.close();});



test('provider acceptance recovery cannot bypass a live initiation lease',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),payments=createPaymentAuthority({db});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:390,currency:'KES',idempotencyKey:'recovery-live-lease-order'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:390});const p=payments.createCommercePayment({orderId:o.id});let correlation;const adapter={initiatePayment:()=>({providerRequestId:'unused'}),lookupPayment:({correlationId})=>({providerRequestId:'provider-accepted',correlationId})};const intents=createPaymentIntentAuthority({db,providers:{test:adapter},leaseMs:60000});const intent=intents.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'test',customerContact:'254700000099',idempotencyKey:'recovery-live-lease-intent'});const claimed=intents.claim({intentId:intent.id,workerId:'active-worker'});assert.equal(claimed.status,'PROCESSING');assert.throws(()=>intents.recoverProviderAcceptance({intentId:intent.id}),e=>e.code==='OUTBOX_ALREADY_LEASED');let row=db.prepare('SELECT status,lease_owner,provider_request_id FROM payment_initiation_outbox WHERE payment_intent_id=?').get(intent.id);assert.equal(row.status,'PROCESSING');assert.equal(row.lease_owner,'active-worker');assert.equal(row.provider_request_id,null);db.prepare('UPDATE payment_initiation_outbox SET lease_expires_at=? WHERE payment_intent_id=?').run(new Date(Date.now()-1000).toISOString(),intent.id);const recovered=intents.recoverProviderAcceptance({intentId:intent.id});assert.equal(recovered.status,'REQUESTED');assert.equal(recovered.provider_request_id,'provider-accepted');row=db.prepare('SELECT status,lease_owner,provider_request_id FROM payment_initiation_outbox WHERE payment_intent_id=?').get(intent.id);assert.equal(row.status,'SENT');assert.equal(row.lease_owner,null);assert.equal(row.provider_request_id,'provider-accepted');db.close();});

test('same initiation worker identity receives a new lease generation after expiry',()=>{const db=openStore(':memory:');const now=new Date().toISOString();db.prepare("INSERT INTO payment_intents(id,payment_kind,payment_id,provider,amount,currency,customer_contact,idempotency_key,correlation_id,status,created_at,updated_at) VALUES('intent-generation','commerce_payment','pay-generation','test',1,'KES','254700000000','idem-generation','corr-generation','PENDING_INITIATION',?,?)").run(now,now);db.prepare("INSERT INTO payment_initiation_outbox(id,payment_intent_id,provider,payload,status,attempts,next_attempt_at,created_at,updated_at) VALUES('out-generation','intent-generation','test','{}','PENDING',0,?,?,?)").run(now,now,now);const authority=createPaymentIntentAuthority({db,providers:{test:{initiatePayment:()=>({providerRequestId:'unused'})}},leaseMs:60000});const first=authority.claim({intentId:'intent-generation',workerId:'worker-same'});assert.equal(first.lease_version,1);db.prepare("UPDATE payment_initiation_outbox SET lease_expires_at=? WHERE id='out-generation'").run(new Date(Date.now()-1000).toISOString());const second=authority.claim({intentId:'intent-generation',workerId:'worker-same'});assert.equal(second.lease_version,2);assert.equal(second.lease_owner,'worker-same');assert.notEqual(first.lease_version,second.lease_version);const staleSuccess=db.prepare("UPDATE payment_initiation_outbox SET status='SENT',lease_owner=NULL,lease_expires_at=NULL,updated_at=? WHERE id=? AND status='PROCESSING' AND lease_owner=? AND lease_version=?").run(new Date().toISOString(),'out-generation','worker-same',first.lease_version);assert.equal(staleSuccess.changes,0);const staleFailure=db.prepare("UPDATE payment_initiation_outbox SET status='FAILED',last_error='STALE',lease_owner=NULL,lease_expires_at=NULL,updated_at=? WHERE id=? AND status='PROCESSING' AND lease_owner=? AND lease_version=?").run(new Date().toISOString(),'out-generation','worker-same',first.lease_version);assert.equal(staleFailure.changes,0);const current=db.prepare("SELECT status,lease_owner,lease_version,last_error FROM payment_initiation_outbox WHERE id='out-generation'").get();assert.equal(current.status,'PROCESSING');assert.equal(current.lease_owner,'worker-same');assert.equal(current.lease_version,2);assert.notEqual(current.last_error,'STALE');db.close();});



test('stale initiation settlement rolls back intent mutation after same worker reacquires newer generation',()=>{const db=openStore(':memory:');const now=new Date('2026-10-02T04:00:00.000Z');db.prepare("INSERT INTO payment_intents(id,payment_kind,payment_id,provider,amount,currency,customer_contact,idempotency_key,correlation_id,status,created_at,updated_at) VALUES('intent-stale-settle','commerce_payment','pay-stale-settle','test',1,'KES','254700000088','idem-stale-settle','corr-stale-settle','PENDING_INITIATION',?,?)").run(now.toISOString(),now.toISOString());db.prepare("INSERT INTO payment_initiation_outbox(id,payment_intent_id,provider,payload,status,attempts,next_attempt_at,created_at,updated_at) VALUES('out-stale-settle','intent-stale-settle','test',?,'PENDING',0,?,?,?)").run(JSON.stringify({idempotencyKey:'corr-stale-settle',correlationId:'corr-stale-settle'}),now.toISOString(),now.toISOString(),now.toISOString());let authority;const adapter={initiatePayment:()=>{db.prepare("UPDATE payment_initiation_outbox SET lease_expires_at=? WHERE id='out-stale-settle'").run(new Date(now.getTime()-1).toISOString());const newer=authority.claim({intentId:'intent-stale-settle',workerId:'same-worker'});assert.equal(newer.lease_version,2);return {providerRequestId:'stale-provider-request'};}};authority=createPaymentIntentAuthority({db,providers:{test:adapter},clock:()=>now,leaseMs:30000});assert.throws(()=>authority.process({intentId:'intent-stale-settle',workerId:'same-worker'}),e=>e.code==='OUTBOX_LEASE_LOST');const out=db.prepare("SELECT status,lease_owner,lease_version,provider_request_id FROM payment_initiation_outbox WHERE id='out-stale-settle'").get();assert.equal(out.status,'PROCESSING');assert.equal(out.lease_owner,'same-worker');assert.equal(out.lease_version,2);assert.equal(out.provider_request_id,null);const intent=authority.get('intent-stale-settle');assert.equal(intent.status,'PENDING_INITIATION');assert.equal(intent.provider_request_id,null);db.close();});


test('stale initiation failure cannot overwrite newer same-worker lease generation',()=>{const db=openStore(':memory:');const now=new Date('2026-10-02T04:30:00.000Z');db.prepare("INSERT INTO payment_intents(id,payment_kind,payment_id,provider,amount,currency,customer_contact,idempotency_key,correlation_id,status,created_at,updated_at) VALUES('intent-stale-fail','commerce_payment','pay-stale-fail','test',1,'KES','254700000087','idem-stale-fail','corr-stale-fail','PENDING_INITIATION',?,?)").run(now.toISOString(),now.toISOString());db.prepare("INSERT INTO payment_initiation_outbox(id,payment_intent_id,provider,payload,status,attempts,next_attempt_at,created_at,updated_at) VALUES('out-stale-fail','intent-stale-fail','test',?,'PENDING',0,?,?,?)").run(JSON.stringify({idempotencyKey:'corr-stale-fail',correlationId:'corr-stale-fail'}),now.toISOString(),now.toISOString(),now.toISOString());let authority;const adapter={initiatePayment:()=>{db.prepare("UPDATE payment_initiation_outbox SET lease_expires_at=? WHERE id='out-stale-fail'").run(new Date(now.getTime()-1).toISOString());const newer=authority.claim({intentId:'intent-stale-fail',workerId:'same-failure-worker'});assert.equal(newer.lease_version,2);throw Object.assign(new Error('stale provider failure'),{code:'STALE_PROVIDER_FAILURE'});}};authority=createPaymentIntentAuthority({db,providers:{test:adapter},clock:()=>now,leaseMs:30000,maxAttempts:1});assert.throws(()=>authority.process({intentId:'intent-stale-fail',workerId:'same-failure-worker'}),e=>e.code==='OUTBOX_LEASE_LOST');const out=db.prepare("SELECT status,attempts,last_error,lease_owner,lease_version FROM payment_initiation_outbox WHERE id='out-stale-fail'").get();assert.equal(out.status,'PROCESSING');assert.equal(out.attempts,0);assert.equal(out.last_error,null);assert.equal(out.lease_owner,'same-failure-worker');assert.equal(out.lease_version,2);const intent=authority.get('intent-stale-fail');assert.equal(intent.status,'PENDING_INITIATION');assert.equal(intent.provider_request_id,null);db.close();});

test('retried initiation requires provider acceptance recovery capability before another outbound request',()=>{const db=openStore(':memory:');const now=new Date().toISOString();db.prepare("INSERT INTO payment_intents(id,payment_kind,payment_id,provider,amount,currency,customer_contact,idempotency_key,correlation_id,status,created_at,updated_at) VALUES('intent-no-lookup','commerce_payment','pay-no-lookup','test',1,'KES','254700000000','idem-no-lookup','corr-no-lookup','PENDING_INITIATION',?,?)").run(now,now);db.prepare("INSERT INTO payment_initiation_outbox(id,payment_intent_id,provider,payload,status,attempts,next_attempt_at,created_at,updated_at) VALUES('out-no-lookup','intent-no-lookup','test',?,'FAILED',1,?,?,?)").run(JSON.stringify({idempotencyKey:'corr-no-lookup',correlationId:'corr-no-lookup'}),now,now,now);db.prepare("UPDATE payment_initiation_outbox SET acceptance_ambiguous=1 WHERE id='out-no-lookup'").run();let initiated=0;const authority=createPaymentIntentAuthority({db,providers:{test:{initiatePayment:()=>{initiated++;return {providerRequestId:'must-not-happen'};}}},maxAttempts:5});assert.throws(()=>authority.processNext({workerId:'retry-no-lookup'}),e=>e.code==='PROVIDER_ACCEPTANCE_RECOVERY_REQUIRED');assert.equal(initiated,0);const row=db.prepare("SELECT status,attempts,last_error FROM payment_initiation_outbox WHERE id='out-no-lookup'").get();assert.equal(row.status,'RECOVERY_REQUIRED');assert.equal(row.attempts,1);assert.equal(row.last_error,'PROVIDER_ACCEPTANCE_RECOVERY_REQUIRED');assert.equal(row.next_attempt_at,undefined);assert.equal(authority.processNext({workerId:'retry-no-lookup-again'}),null);const parked=db.prepare("SELECT status,attempts,acceptance_ambiguous FROM payment_initiation_outbox WHERE id='out-no-lookup'").get();assert.equal(parked.status,'RECOVERY_REQUIRED');assert.equal(parked.attempts,1);assert.equal(parked.acceptance_ambiguous,1);db.close();});

test('payment initiation runtime drains bounded due work and isolates provider failures',()=>{let calls=0;const authority={processNext:()=>{calls++;if(calls===1)throw Object.assign(new Error('PROVIDER_DOWN'),{code:'PROVIDER_DOWN'});if(calls===2)return {id:'recovered'};return null;}};const runtime=createPaymentInitiationRuntime({authority,batchSize:5,setIntervalFn:()=>({unref(){}}),clearIntervalFn:()=>{}});runtime.start();assert.equal(calls,3);assert.equal(runtime.running,false);runtime.stop();});

test('payment initiation runtime prevents overlapping drains and stops cleanly',()=>{let scheduled,cleared=false,calls=0;const authority={processNext:()=>{calls++;return null;}};const runtime=createPaymentInitiationRuntime({authority,setIntervalFn:fn=>{scheduled=fn;return {unref(){}};},clearIntervalFn:()=>{cleared=true;}});runtime.start();assert.equal(calls,1);scheduled();assert.equal(calls,2);runtime.stop();assert.equal(cleared,true);assert.deepEqual(runtime.drain(),[]);});

test('side-effect runtime drains startup backlog and stops cleanly',()=>{const db=openStore(':memory:');let delivered=0,scheduled=null,cleared=false;const outbox=createPaymentSideEffectOutbox({db,handlers:{TEST_EFFECT:()=>{delivered++;}}});db.exec('BEGIN IMMEDIATE');outbox.enqueueInsideTransaction({eventKey:'runtime-startup-1',effectType:'TEST_EFFECT',payload:{}});db.exec('COMMIT');const runtime=createSideEffectRuntime({outbox,workerId:'runtime-worker',setIntervalFn:fn=>{scheduled=fn;return {unref(){}};},clearIntervalFn:()=>{cleared=true;}});runtime.start();assert.equal(delivered,1);assert.equal(db.prepare("SELECT status FROM payment_side_effect_outbox WHERE event_key='runtime-startup-1'").get().status,'DELIVERED');assert.equal(typeof scheduled,'function');runtime.stop();assert.equal(cleared,true);db.close();});

test('side-effect runtime does not overlap drains',()=>{let calls=0,reenter;const outbox={processDue:()=>{calls++;if(reenter)reenter();return [];}};const runtime=createSideEffectRuntime({outbox,workerId:'runtime-no-overlap',setIntervalFn:()=>({unref(){}}),clearIntervalFn:()=>{}});reenter=()=>runtime.drain();runtime.start();assert.equal(calls,1);runtime.stop();});

test('commerce payment creation requires authoritative price confirmation',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),payments=createPaymentAuthority({db});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:100,currency:'KES',idempotencyKey:'price-bind-required'});orders.transition({orderId:o.id,to:'VALIDATED'});db.prepare("UPDATE commerce_orders SET status='PAYMENT_PENDING' WHERE id=?").run(o.id);assert.throws(()=>payments.createCommercePayment({orderId:o.id}),e=>e.code==='PRICE_CONFIRMATION_REQUIRED');assert.equal(db.prepare('SELECT COUNT(*) AS n FROM commerce_payments WHERE order_id=?').get(o.id).n,0);db.close();});
test('commerce payment rejects stale inventory version after price confirmation',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),payments=createPaymentAuthority({db}),inventory=createInventoryAuthority({db});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:100,currency:'KES',idempotencyKey:'price-bind-stale'});orders.transition({orderId:o.id,to:'VALIDATED'});const {merchant}=makePayableCommerce({db,orders,order:o,unitPrice:100});inventory.setStock({merchantId:'m1',sku:'x',quantity:5,unitPrice:101,currency:'KES',actor:merchant});assert.throws(()=>payments.createCommercePayment({orderId:o.id}),e=>e.code==='PRICE_CONFIRMATION_STALE');assert.equal(db.prepare('SELECT COUNT(*) AS n FROM commerce_payments WHERE order_id=?').get(o.id).n,0);db.close();});

test('repricing preserves historical confirmation and requires customer acknowledgement before payment',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),inventory=createInventoryAuthority({db}),pricing=createPricingAuthority({db}),payments=createPaymentAuthority({db}),merchant={id:'m1',role:'agent'};const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:2}],total:200,currency:'KES',idempotencyKey:'reprice-1'});orders.transition({orderId:o.id,to:'VALIDATED'});inventory.setStock({merchantId:'m1',sku:'x',quantity:5,unitPrice:100,currency:'KES',actor:merchant});const first=pricing.confirm({orderId:o.id,actor:merchant});orders.transition({orderId:o.id,to:'PAYMENT_PENDING'});inventory.setStock({merchantId:'m1',sku:'x',quantity:5,unitPrice:125,currency:'KES',actor:merchant});assert.throws(()=>payments.createCommercePayment({orderId:o.id}),e=>e.code==='PRICE_CONFIRMATION_STALE');const second=pricing.reprice({orderId:o.id,actor:merchant});assert.equal(second.amount,250);assert.equal(second.supersedes_id,first.id);assert.equal(db.prepare('SELECT status FROM commerce_price_confirmations WHERE id=?').get(first.id).status,'SUPERSEDED');assert.equal(db.prepare('SELECT total FROM commerce_orders WHERE id=?').get(o.id).total,250);orders.transition({orderId:o.id,to:'PAYMENT_PENDING'});assert.throws(()=>payments.createCommercePayment({orderId:o.id}),e=>e.code==='PRICE_ACKNOWLEDGEMENT_REQUIRED');pricing.acknowledge({orderId:o.id,customerId:'c1'});const p=payments.createCommercePayment({orderId:o.id});assert.equal(p.amount,250);assert.equal(db.prepare('SELECT COUNT(*) AS n FROM commerce_price_confirmations WHERE order_id=?').get(o.id).n,2);db.close();});
test('repricing cannot replace evidence after payment exists and acknowledgement is customer-bound',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),inventory=createInventoryAuthority({db}),pricing=createPricingAuthority({db}),payments=createPaymentAuthority({db}),merchant={id:'m1',role:'agent'};const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:100,currency:'KES',idempotencyKey:'reprice-guards'});orders.transition({orderId:o.id,to:'VALIDATED'});inventory.setStock({merchantId:'m1',sku:'x',quantity:5,unitPrice:100,currency:'KES',actor:merchant});pricing.confirm({orderId:o.id,actor:merchant});orders.transition({orderId:o.id,to:'PAYMENT_PENDING'});const p=payments.createCommercePayment({orderId:o.id});assert.ok(p.id);inventory.setStock({merchantId:'m1',sku:'x',quantity:5,unitPrice:110,currency:'KES',actor:merchant});assert.throws(()=>pricing.reprice({orderId:o.id,actor:merchant}),e=>e.code==='PAYMENT_ALREADY_EXISTS');assert.throws(()=>pricing.acknowledge({orderId:o.id,customerId:'other'}),e=>e.code==='PRICE_ACKNOWLEDGEMENT_FORBIDDEN');db.close();});

test('payment outbox worker claims once and competing worker cannot process active lease',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),payments=createPaymentAuthority({db});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:330,currency:'KES',idempotencyKey:'worker-lease'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:330});const p=payments.createCommercePayment({orderId:o.id});let calls=0;const intents=createPaymentIntentAuthority({db,providers:{mpesa:{initiatePayment:()=>{calls++;return {providerRequestId:'lease-1'}}}}});const i=intents.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'mpesa',customerContact:'254700000020',idempotencyKey:'worker-lease-i'});const claimed=intents.claim({intentId:i.id,workerId:'w1'});assert.equal(claimed.status,'PROCESSING');assert.throws(()=>intents.claim({intentId:i.id,workerId:'w2'}),e=>e.code==='OUTBOX_ALREADY_LEASED');assert.equal(calls,0);db.close();});
test('payment outbox failure schedules exponential retry and eventually dead letters',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),payments=createPaymentAuthority({db});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:340,currency:'KES',idempotencyKey:'worker-retry'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:340});const p=payments.createCommercePayment({orderId:o.id});let now=new Date('2026-10-01T10:00:00.000Z'),calls=0;const intents=createPaymentIntentAuthority({db,clock:()=>now,maxAttempts:2,baseBackoffMs:1000,providers:{mpesa:{initiatePayment:()=>{calls++;throw Object.assign(new Error('down'),{code:'PROVIDER_DOWN'});}}}});const i=intents.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'mpesa',customerContact:'254700000021',idempotencyKey:'worker-retry-i'});assert.throws(()=>intents.process({intentId:i.id,workerId:'w1'}),e=>e.code==='PROVIDER_DOWN');let out=db.prepare('SELECT * FROM payment_initiation_outbox WHERE payment_intent_id=?').get(i.id);assert.equal(out.status,'FAILED');assert.equal(out.attempts,1);assert.equal(out.next_attempt_at,'2026-10-01T10:00:01.000Z');assert.throws(()=>intents.process({intentId:i.id,workerId:'w2'}),e=>e.code==='OUTBOX_NOT_DUE');now=new Date('2026-10-01T10:00:01.000Z');assert.throws(()=>intents.process({intentId:i.id,workerId:'w2'}),e=>e.code==='PROVIDER_DOWN');out=db.prepare('SELECT * FROM payment_initiation_outbox WHERE payment_intent_id=?').get(i.id);assert.equal(out.status,'DEAD_LETTER');assert.equal(out.attempts,2);assert.equal(out.next_attempt_at,null);assert.equal(calls,2);db.close();});
test('expired payment outbox lease is recoverable by another worker',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),payments=createPaymentAuthority({db});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:350,currency:'KES',idempotencyKey:'worker-recover'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:350});const p=payments.createCommercePayment({orderId:o.id});let now=new Date('2026-10-01T11:00:00.000Z');const intents=createPaymentIntentAuthority({db,clock:()=>now,leaseMs:1000,providers:{mpesa:{initiatePayment:()=>({providerRequestId:'recovered'})}}});const i=intents.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'mpesa',customerContact:'254700000022',idempotencyKey:'worker-recover-i'});intents.claim({intentId:i.id,workerId:'crashed'});now=new Date('2026-10-01T11:00:02.000Z');const claimed=intents.claim({intentId:i.id,workerId:'recovery'});assert.equal(claimed.lease_owner,'recovery');assert.equal(claimed.status,'PROCESSING');db.close();});

test('provider initiation uses stable correlation id as provider idempotency key',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),payments=createPaymentAuthority({db});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:360,currency:'KES',idempotencyKey:'provider-idem-order'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:360});const p=payments.createCommercePayment({orderId:o.id});let seen;const adapter=createMpesaAdapter({initiate:req=>{seen=req;return {providerRequestId:'provider-idem-1'}}});const intents=createPaymentIntentAuthority({db,providers:{mpesa:adapter}});const i=intents.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'mpesa',customerContact:'254700000030',idempotencyKey:'provider-idem-intent'});intents.process({intentId:i.id});assert.equal(seen.idempotencyKey,i.correlation_id);assert.equal(seen.correlationId,i.correlation_id);const out=db.prepare('SELECT * FROM payment_initiation_outbox WHERE payment_intent_id=?').get(i.id);assert.equal(out.status,'SENT');assert.ok(out.provider_acknowledgement);assert.ok(out.provider_acknowledged_at);db.close();});
test('provider acceptance recovery closes crash window without duplicate initiation',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),payments=createPaymentAuthority({db});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:370,currency:'KES',idempotencyKey:'provider-recover-order'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:370});const p=payments.createCommercePayment({orderId:o.id});let initiateCalls=0,lookupCalls=0,accepted=false,providerRequestId;const adapter=createMpesaAdapter({initiate:req=>{initiateCalls++;accepted=true;providerRequestId='accepted-'+req.correlationId;throw Object.assign(new Error('simulated crash after provider acceptance'),{code:'TRANSPORT_LOST_AFTER_ACCEPT'});},lookup:({correlationId})=>{lookupCalls++;return accepted?{providerRequestId,correlationId}:null;}});let now=new Date('2026-10-01T12:00:00.000Z');const intents=createPaymentIntentAuthority({db,clock:()=>now,baseBackoffMs:1000,providers:{mpesa:adapter}});const i=intents.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'mpesa',customerContact:'254700000031',idempotencyKey:'provider-recover-intent'});assert.throws(()=>intents.process({intentId:i.id,workerId:'w1'}),e=>e.code==='TRANSPORT_LOST_AFTER_ACCEPT');assert.equal(initiateCalls,1);now=new Date('2026-10-01T12:00:01.000Z');const recovered=intents.process({intentId:i.id,workerId:'w2'});assert.equal(recovered.status,'REQUESTED');assert.equal(recovered.provider_request_id,providerRequestId);assert.equal(initiateCalls,1);assert.ok(lookupCalls>=1);const out=db.prepare('SELECT * FROM payment_initiation_outbox WHERE payment_intent_id=?').get(i.id);assert.equal(out.status,'SENT');const evidence=JSON.parse(out.provider_acknowledgement);assert.equal(evidence.recovered,true);assert.equal(evidence.providerRequestId,providerRequestId);db.close();});

test('payment initiation runtime recovers provider acceptance after restart without duplicate initiation',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),payments=createPaymentAuthority({db});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:375,currency:'KES',idempotencyKey:'runtime-provider-recover-order'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:375});const p=payments.createCommercePayment({orderId:o.id});let initiateCalls=0,lookupCalls=0,accepted=false,providerRequestId,now=new Date('2026-10-01T12:30:00.000Z');const adapter=createMpesaAdapter({initiate:req=>{initiateCalls++;accepted=true;providerRequestId='runtime-accepted-'+req.correlationId;throw Object.assign(new Error('simulated runtime crash after provider acceptance'),{code:'TRANSPORT_LOST_AFTER_ACCEPT',acceptanceAmbiguous:true});},lookup:({correlationId})=>{lookupCalls++;return accepted?{providerRequestId,correlationId}:null;}});const authority=createPaymentIntentAuthority({db,clock:()=>now,baseBackoffMs:1000,providers:{mpesa:adapter}});const intent=authority.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'mpesa',customerContact:'254700000033',idempotencyKey:'runtime-provider-recover-intent'});const first=createPaymentInitiationRuntime({authority,workerId:'runtime-before-crash',batchSize:1,setIntervalFn:()=>({unref(){}}),clearIntervalFn:()=>{}});first.start();first.stop();let out=db.prepare('SELECT * FROM payment_initiation_outbox WHERE payment_intent_id=?').get(intent.id);assert.equal(out.status,'FAILED');assert.equal(initiateCalls,1);now=new Date('2026-10-01T12:30:01.000Z');const restarted=createPaymentInitiationRuntime({authority,workerId:'runtime-after-restart',batchSize:1,setIntervalFn:()=>({unref(){}}),clearIntervalFn:()=>{}});restarted.start();restarted.stop();out=db.prepare('SELECT * FROM payment_initiation_outbox WHERE payment_intent_id=?').get(intent.id);assert.equal(out.status,'SENT');assert.equal(initiateCalls,1);assert.ok(lookupCalls>=1);const recovered=authority.get(intent.id);assert.equal(recovered.status,'REQUESTED');assert.equal(recovered.provider_request_id,providerRequestId);const evidence=JSON.parse(out.provider_acknowledgement);assert.equal(evidence.recovered,true);assert.equal(evidence.providerRequestId,providerRequestId);db.close();});


test('ambiguous initiation failure persists recovery requirement and restart uses lookup without duplicate initiate',()=>{const db=openStore(':memory:');const now=new Date().toISOString();db.prepare("INSERT INTO payment_intents(id,payment_kind,payment_id,provider,amount,currency,customer_contact,idempotency_key,correlation_id,status,created_at,updated_at) VALUES('intent-ambiguous-contract','commerce_payment','pay-ambiguous-contract','test',1,'KES','254700000099','idem-ambiguous-contract','corr-ambiguous-contract','PENDING_INITIATION',?,?)").run(now,now);db.prepare("INSERT INTO payment_initiation_outbox(id,payment_intent_id,provider,payload,status,attempts,next_attempt_at,created_at,updated_at) VALUES('out-ambiguous-contract','intent-ambiguous-contract','test',?,'PENDING',0,?,?,?)").run(JSON.stringify({idempotencyKey:'corr-ambiguous-contract',correlationId:'corr-ambiguous-contract'}),now,now,now);let initiateCalls=0,lookupCalls=0,accepted=false;const providerRequestId='accepted-ambiguous-contract';const adapter={initiatePayment:()=>{initiateCalls++;accepted=true;throw Object.assign(new Error('response lost after acceptance'),{code:'TRANSPORT_LOST_AFTER_ACCEPT',acceptanceAmbiguous:true});},lookupPayment:({correlationId})=>{lookupCalls++;return accepted?{providerRequestId,correlationId}:null;}};const authority=createPaymentIntentAuthority({db,providers:{test:adapter},baseBackoffMs:0});assert.throws(()=>authority.processNext({workerId:'ambiguous-first-worker'}),e=>e.code==='TRANSPORT_LOST_AFTER_ACCEPT');let out=db.prepare("SELECT * FROM payment_initiation_outbox WHERE id='out-ambiguous-contract'").get();assert.equal(out.status,'FAILED');assert.equal(out.acceptance_ambiguous,1);assert.equal(initiateCalls,1);out.next_attempt_at=now;db.prepare("UPDATE payment_initiation_outbox SET next_attempt_at=? WHERE id='out-ambiguous-contract'").run(now);authority.processNext({workerId:'ambiguous-restart-worker'});out=db.prepare("SELECT * FROM payment_initiation_outbox WHERE id='out-ambiguous-contract'").get();assert.equal(out.status,'SENT');assert.equal(out.acceptance_ambiguous,0);assert.equal(initiateCalls,1);assert.ok(lookupCalls>=1);assert.equal(out.provider_request_id,providerRequestId);const intent=authority.get('intent-ambiguous-contract');assert.equal(intent.status,'REQUESTED');assert.equal(intent.provider_request_id,providerRequestId);db.close();});

test('provider recovery rejects correlation mismatch evidence',()=>{const db=openStore(':memory:');const orders=createOrderAuthority({db}),payments=createPaymentAuthority({db});const o=orders.create({customerId:'c1',merchantId:'m1',basket:[{sku:'x',qty:1}],total:380,currency:'KES',idempotencyKey:'provider-mismatch-order'});orders.transition({orderId:o.id,to:'VALIDATED'});makePayableCommerce({db,orders,order:o,unitPrice:380});const p=payments.createCommercePayment({orderId:o.id});const adapter=createMpesaAdapter({initiate:()=>({providerRequestId:'unused'}),lookup:()=>({providerRequestId:'wrong',correlationId:'different'})});const intents=createPaymentIntentAuthority({db,providers:{mpesa:adapter}});const i=intents.create({paymentKind:'commerce_payment',paymentId:p.id,provider:'mpesa',customerContact:'254700000032',idempotencyKey:'provider-mismatch-intent'});assert.throws(()=>intents.recoverProviderAcceptance({intentId:i.id}),e=>e.code==='PROVIDER_CORRELATION_MISMATCH');assert.equal(intents.get(i.id).status,'PENDING_INITIATION');db.close();});
